void test_FR_010_01(void)
{
    motion_sample_t sample;
    motion_processor_status_t status;
    int32_t bump_raw;

    status = motion_processor_process(0, 0, (int16_t)APP_MOTION_SENSITIVITY_LSB_PER_G, 0U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_CALIBRATING, status);

    status = motion_processor_process(0, 0, (int16_t)APP_MOTION_SENSITIVITY_LSB_PER_G,
                                     APP_MOTION_CALIBRATION_DURATION_MS, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);

    /* Choose a Z-axis change that converts to more than the speed-breaker threshold. */
    bump_raw = (((int32_t)APP_MOTION_SPEED_BREAKER_THRESHOLD_MILLIG + 1) *
                (int32_t)APP_MOTION_SENSITIVITY_LSB_PER_G + 999) / 1000;
    status = motion_processor_process(0, 0,
                                     (int16_t)((int32_t)APP_MOTION_SENSITIVITY_LSB_PER_G + bump_raw),
                                     APP_MOTION_CALIBRATION_DURATION_MS + APP_MOTION_IDLE_DELAY_MS,
                                     &sample);

    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_TRUE(sample.z_millig > APP_MOTION_SPEED_BREAKER_THRESHOLD_MILLIG);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_UNSEEN_SPEED_BREAKER, sample.event);
}
